"""Copy-ready review comments, generated by code (no LLM), from the analysis results."""

FOOTER = (
    "_Generated from a code + git knowledge graph. Static analysis lists the dependents it can see; "
    "it cannot prove that a change is safe._"
)


def _factors(rep: dict) -> list[str]:
    return [f"- **{f['factor']}** (+{f['points']}): {f['detail']}" for f in rep["factors"] if f["points"] > 0] or [
        "- no risk factors triggered"
    ]


def _reviewers(reviewers: list[dict]) -> list[str]:
    if not reviewers:
        return ["- none found (no ownership data)"]
    return [f"- **{r['name']}**: " + "; ".join(r["reasons"]) for r in reviewers]


def function_comment(rep: dict) -> str:
    br = rep["blast"]
    t = br["target"]
    tests = rep["tests_to_run"]
    hidden = rep["hidden"]
    lines = [
        f"### Safe-Change review: `{t['qualname']}`: {rep['level']} risk (score {rep['score']})",
        f"`{t['file']}:{t['lineno']}`",
        "",
        "**Why**",
        *_factors(rep),
        "",
        f"**Known dependents:** {len(br['prod_callers'])} production function(s) in {len(br['impacted_files'])} other file(s)",
    ]
    for c in br["prod_callers"][:6]:
        lines.append(f"- hop {c['hops']}: `{c['qualname']}` ({c['file']})")
    lines += ["", "**Tests to run**", "- reach it through code: " + (", ".join(tests["static"]) or "none found")]
    if tests["co_changed"]:
        lines.append("- usually change with this file: " + ", ".join(tests["co_changed"]))
    if hidden["hidden"]:
        lines += ["", "**Easy to miss: changes together with this file but has no code link**"]
        lines += [f"- `{h['path']}` [{h['kind']}]: {h['together']} of {hidden['total']} commits" for h in hidden["hidden"][:5]]
    if rep["blind_spots"]:
        lines += ["", "**Blind spots**"] + [f"- {b['text']}" for b in rep["blind_spots"][:4]]
    lines += ["", "**Suggested reviewers**", *_reviewers(rep["reviewers"]), "", FOOTER]
    return "\n".join(lines)


def diff_comment(res: dict) -> str:
    lines = [f"### Safe-Change review of this change: {res['overall']} risk", ""]
    if res["reports"]:
        lines += ["| Function | File | Risk | Dependents | Test files |", "|---|---|---|---|---|"]
        for rep in res["reports"]:
            t = rep["blast"]["target"]
            lines.append(
                f"| `{t['qualname']}` | {t['file']} | {rep['level']} ({rep['score']}) | "
                f"{len(rep['blast']['prod_callers'])} | {len(rep['tests_to_run']['static'])} |"
            )
    for cc in res["class_changes"]:
        lines.append(f"\n- class `{cc['qualname']}` body changed: created in {len(cc['instantiators'])} place(s), {len(cc['subclasses'])} subclass(es)")
    for mc in res["module_changes"]:
        lines.append(f"\n- module-level change in `{mc['file']}`: imported by {len(mc['importers'])} file(s)")
    if res["new_files"]:
        lines.append("\nNew files: " + ", ".join(f"`{f}`" for f in res["new_files"]))

    if res["missing_cochanged"]:
        lines += ["", "**Usually changes together with these files, but is NOT in this change (check it)**"]
        for m in res["missing_cochanged"]:
            lines.append(f"- `{m['path']}` [{m['kind']}]: {m['together']} of {m['total']} commits touching `{m['changed']}`")

    tests = sorted({f for r in res["reports"] for f in r["tests_to_run"]["static"]})
    co = sorted({f for r in res["reports"] for f in r["tests_to_run"]["co_changed"]} - set(tests))
    lines += ["", "**Tests to run**", "- " + (", ".join(tests) or "none found through code")]
    if co:
        lines.append("- usually change with these files: " + ", ".join(co))
    spots = []
    for rep in res["reports"]:
        for b in rep["blind_spots"]:
            if b["kind"] in ("escapes", "returns_callable", "decorated", "string_mentions") and b["text"] not in spots:
                spots.append(b["text"])
    if spots:
        lines += ["", "**Blind spots**"] + [f"- {s}" for s in spots[:4]]
    lines += ["", "**Suggested reviewers**", *_reviewers(res["reviewers"]), "", FOOTER]
    return "\n".join(lines)
